/* Letters come out of a blur one after another as the text scrolls into view, left to right.
   Every letter has its own view timeline; the stagger is an offset on its animation range
   (--on-energy-blur-i is the letter's index). */
.on-energy-blur-text-word {
  display: inline-block;
  white-space: nowrap;
}
.on-energy-blur-text-letter {
  display: inline-block;
}

@supports (animation-timeline: view()) {
  .on-energy-blur-text-letter {
    animation: on-energy-blur-text-in linear both;
    animation-timeline: view();
    animation-range:
      cover calc(2% + var(--on-energy-blur-i, 0) * 0.25%)
      cover calc(10% + var(--on-energy-blur-i, 0) * 0.25%);
  }
}

@keyframes on-energy-blur-text-in {
  from { opacity: 0; filter: blur(10px); }
  to { opacity: 1; filter: blur(0); }
}

@media (prefers-reduced-motion: reduce) {
  .on-energy-blur-text-letter { animation: none !important; }
}

import { Fragment, type CSSProperties, type ElementType } from "react";
import { cn } from "@foundry/foundry-utils";
import "./on-energy-blur-text.css";

export interface OnEnergyBlurTextProps {
  /** the text; a "\n" starts a new line */
  text: string;
  /** the element to render, e.g. "h2", "h3", "p" (default "h2") */
  as?: ElementType;
  className?: string;
}

/**
 * Heading text whose letters sharpen out of a blur one by one, left to right, as it scrolls
 * into view (CSS scroll-driven, no JavaScript). Static HTML and browsers without
 * scroll-driven animations show the text as is.
 */
export function OnEnergyBlurText({ text, as: Tag = "h2", className }: OnEnergyBlurTextProps) {
  let index = 0;
  const lines = text.split("\n");
  return (
    <Tag className={cn(className)} aria-label={text.replace(/\n/g, " ")}>
      {lines.map((line, l) => (
        <Fragment key={l}>
          {l > 0 && <br />}
          {line.split(" ").map((word, w) => (
            <Fragment key={w}>
              {w > 0 && " "}
              <span aria-hidden className="on-energy-blur-text-word">
                {[...word].map((ch, c) => (
                  <span key={c} className="on-energy-blur-text-letter" style={{ "--on-energy-blur-i": index++ } as CSSProperties}>
                    {ch}
                  </span>
                ))}
              </span>
            </Fragment>
          ))}
        </Fragment>
      ))}
    </Tag>
  );
}
